rows = [json.loads(line) for line in src.read_text(encoding="utf-8").splitlines() if line.strip()]
out = []
for row in rows:
    phrase = row["canonicalPhrase"]
    zh = meaning.get(phrase, "")
    status = "GENERATED" if zh else "REVIEW_REQUIRED"
    out.append({"id": row["id"], "canonicalPhrase": phrase, "meaningZh": zh, "usageNoteZh": "", "translationStatus": status, "confidence": "HIGH" if zh else "LOW"})
dst.write_text("\n".join(json.dumps(x, ensure_ascii=False) for x in out) + "\n", encoding="utf-8")
assert len(out) == 300
assert all(list(x) == ["id", "canonicalPhrase", "meaningZh", "usageNoteZh", "translationStatus", "confidence"] for x in out)
assert [x["id"] for x in out] == [x["id"] for x in rows]
assert [x["canonicalPhrase"] for x in out] == [x["canonicalPhrase"] for x in rows]
print(f"wrote {len(out)} rows; generated={sum(x['translationStatus']=='GENERATED' for x in out)}; review={sum(x['translationStatus']=='REVIEW_REQUIRED' for x in out)}")
